 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    # The picture has a one-cell background, a color-4 frame, then a
    # diagonal periodic color field. Infer its period and phase colors from
    # the visible (non-hole) cells.
    observations = [
        (r + c, grid[r][c])
        for r in range(3, h)
        for c in range(3, w)
        if grid[r][c] != 0
    ]
    best = None
    for period in range(2, min(15, h + w) + 1):
        bins = [[] for _ in range(period)]
        for phase, color in observations:
            bins[phase % period].append(color)
        mapping = [Counter(b).most_common(1)[0][0] if b else None for b in bins]
        errors = sum(mapping[phase % period] != color for phase, color in observations)
        covered = sum(bool(b) for b in bins)
        # Prefer the simplest period at equal error; coverage discourages
        # spurious large periods when some phases are hidden.
        score = (errors, -covered, period)
        if best is None or score < best[0]:
            best = (score, period, mapping)
    _, period, mapping = best

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                color = mapping[(r + c) % period]
                if color is None:
                    # A phase not seen in the input: infer from neighboring
                    # phases in the repeating sequence.
                    for delta in range(1, period + 1):
                        color = mapping[((r + c) + delta) % period]
                        if color is not None:
                            break
                out[r][c] = color
    return out
